sys_ws_operation.operation_script:
(function process(request, response) {

    // =========================================================
    // 1. CURRENT LOGGED-IN EMPLOYEE
    // =========================================================
    var employeeId = gs.getUserID();


    // =========================================================
    // 2. QUERY EMPLOYEE ATTENDANCE
    // =========================================================
    var attendance =
        new GlideRecord(
            'x_1760545_smarta_0_attendance'
        );

    attendance.addQuery(
        'employee',
        employeeId
    );

    attendance.orderByDesc(
        'attendance_date'
    );

    attendance.setLimit(30);

    attendance.query();


    var records = [];


    // =========================================================
    // 3. BUILD RESPONSE
    // =========================================================
    while (attendance.next()) {

        records.push({

            number:
                attendance.getValue(
                    'number'
                ),

            attendance_id:
                attendance.getUniqueValue(),

            attendance_date:
                attendance.getValue(
                    'attendance_date'
                ),

            status:
                attendance.getValue(
                    'status'
                ),

            check_in:
                convertToIndiaTime(
                    attendance.getValue(
                        'check_in'
                    )
                ),

            check_out:
                convertToIndiaTime(
                    attendance.getValue(
                        'check_out'
                    )
                ),

            late_minutes:
                attendance.getValue(
                    'late_minutes'
                ) || '0',

            working_minutes:
                attendance.getValue(
                    'working_minutes'
                ) || '',

            scanner:
                attendance.scanner
                    .getDisplayValue()

        });
    }


    // =========================================================
    // 4. RETURN
    // =========================================================
    response.setStatus(200);

    response.setBody({

        success: true,

        employee:
            gs.getUserDisplayName(),

        count:
            records.length,

        attendance:
            records

    });


    // =========================================================
    // HELPER - CONVERT STORED UTC TO INDIA TIME
    // =========================================================
    function convertToIndiaTime(value) {

        if (!value) {
            return '';
        }


        var dateTime =
            new GlideDateTime(
                value
            );


        // India = UTC + 5:30
        dateTime.addSeconds(
            19800
        );


        return dateTime.getValue();
    }

})(request, response);
